(** ChshPhases.v: generated by scripts/generate_chsh_phases.py.
    The CHSH_LASSERT FSM rule at each concrete phase, with the phase
    multiplexers resolved. Each equation is checked by the kernel. *)
Require Import Kami.Kami Kami.Semantics.
From Coq Require Import String.
From KamiHW Require Import ThieleTypes ThieleCPUCore HWBoundary RuleNext ChshDecoded ChshArith ChshFsm.

(** Resolve the phase multiplexers with tactics before conversion: left to the
    kernel, the same check unfolds the wide word operations and takes minutes. *)
Ltac phase_mux :=
  cbn [evalExpr evalUniBool evalBinBitBool evalConstT isEq evalUniBit evalBinBit];
  repeat match goal with |- context [weq ?x ?y] =>
    let v := eval vm_compute in (if weq x y then true else false) in
    change (if weq x y then true else false) with v end;
  cbv beta iota.

Ltac phase_unfold :=
  unfold chsh_commit_trap, chsh_mult_128, chsh_mult_256, chsh_mult_384, chsh_mult_result_768,
    chsh_op_a_384, chsh_op_b_384, chsh_phase_eq_1, chsh_phase_eq_2, chsh_phase_eq_3, chsh_phase_eq_4, chsh_phase_eq_5, chsh_phase_eq_6, chsh_phase_eq_7, chsh_phase_eq_8, chsh_phase_eq_9, chsh_phase_eq_10, chsh_phase_eq_11, chsh_phase_eq_12, chsh_phase_eq_13, chsh_phase_eq_14, chsh_phase_eq_15, chsh_phase_eq_16, chsh_phase_eq_17, chsh_phase_eq_18, chsh_phase_eq_19, chsh_phase_eq_20, chsh_phase_eq_21, chsh_phase_eq_22, chsh_phase_eq_23.

Lemma chsh_eq1_at1 : forall b, hw_chsh_phase b = natToWord 5 1 -> chsh_phase_eq_1 b = true.
Proof. intros b H. unfold chsh_phase_eq_1. cbn [evalExpr evalConstT isEq]. rewrite H. reflexivity. Qed.
